#include "strata/kernels/original_mtp53_joint_capture_restore.hpp"
using namespace strata::kernels::original_mtp53;
std::shared_ptr<const OriginalJointCheckpoint53> compile_joint_capture53(OriginalServingSlots53& draft,int slot,OriginalDraftSlotOwner53 who,const std::array<JointTargetSlot53,2>& stages,const std::array<strata::core::ConversationView,2>& views,const strata::core::ModelGeometry& geometry,const std::function<OriginalDraftSlotOwner53()>& current){return capture_joint53(draft,slot,who,stages,views,geometry,std::string(64,'a'),std::string(64,'b'),current);}
void compile_joint_restore53(const std::shared_ptr<const OriginalJointCheckpoint53>& image,OriginalServingSlots53& draft,int slot,OriginalDraftSlotOwner53 who,const std::array<JointTargetSlot53,2>& stages,const strata::core::ModelGeometry& geometry,const std::function<OriginalDraftSlotOwner53()>& current){restore_joint53(image,image->digest(),draft,slot,who,stages,geometry,std::string(64,'a'),std::string(64,'b'),current);}
